{"results": [{"id": "hp_doc_f8f1ca481c625460242579c7a2f4526768950878a3bcd2ee7e3b19e8e973cdd4", "title": "2010 Pepsi Max 400", "text": "The 2010 Pepsi Max 400 was a NASCAR Sprint Cup Series stock car race that was held on October 10, 2010, at Auto Club Speedway in Fontana, California. Contested over 200 laps, it was the 30th race of the 2010 NASCAR Sprint Cup Series season and the fourth race in the season-ending Chase for the Sprint Cup. The race was won by Tony Stewart of the Stewart-Haas Racing team, while Clint Bowyer finished second, and Jimmie Johnson clinched third.", "score": 32.6206}, {"id": "hp_doc_4c41d0dbe16cbdc1928794aa03184f3be53c6ca2b987d5b075d36bd2a1e8595e", "title": "Pepsi Max 400", "text": "The Pepsi Max 400 was a NASCAR Sprint Cup Series stock car race held annually at the Auto Club Speedway in Fontana, California. It was the second of two Sprint Cup Series races held at the Auto Club Speedway (the other being the Auto Club 500) and in 2009 and 2010 it was run in October as part of the Chase for the Sprint Cup.", "score": 29.2186}, {"id": "hp_doc_7b86e1c847ead283ff12c103eeafd6bb6f31003809a7ba361b5821bde1b7fe17", "title": "Pepsi Max", "text": "Pepsi Max (also known as Pepsi Black in some countries) is a low-calorie, sugar-free cola, marketed by PepsiCo as an alternative to their drinks Pepsi and Diet Pepsi. It is sold primarily in European and Asian markets.", "score": 22.4282}], "remaining_searches": 2}
