{"results": [{"id": "hp_doc_7fc3a23e414e5189aead8b224feeb799169da033b4d7d7a38302c0238342f2bf", "title": "Hancock, West Virginia", "text": "Hancock is an unincorporated community hamlet in Morgan County in the U.S. state of West Virginia's Eastern Panhandle. It is located off Hancock Road (U.S. Route 522) on River Road (West Virginia Secondary Route 1) along the Potomac River north of Berkeley Springs. Originally known as Brosius, its post office's name was changed to Hancock in 1948 to reflect its location on the Baltimore and Ohio Railroad mainline across the river from Hancock, Maryland.", "score": 24.0421}, {"id": "hp_doc_d93c9c1d8bfe5bf9b4e42259d694398b67287c6df06562424709bb72fd248f44", "title": "Hancock, Pennsylvania", "text": "Hancock is an unincorporated community in Longswamp Township in Berks County, Pennsylvania, United States. Hancock is located at the intersection of State Street and Park Avenue.", "score": 19.7618}, {"id": "hp_doc_c5682511e137f5928a93deb402593720c24ec0f8bb20dfff27d77687f489fcc6", "title": "Charlottesville, Indiana", "text": "Charlottesville is an unincorporated community in Hancock and Rush counties in the U.S. state of Indiana. The Hancock County portion is in Jackson Township, while the Rush County portion is in Ripley Township.", "score": 17.9235}], "remaining_searches": 2}
